import { z } from 'zod';
import { errorPayloadSchema } from './errors';

/**
 * Maximum serialised request payload size accepted at the IPC boundary.
 * Keeps a single malformed/oversized call from stressing the main process.
 */
export const MAX_PAYLOAD_BYTES = 64 * 1024;

/**
 * A UUID generated by the renderer/preload and echoed back as correlationId.
 */
export const requestIdSchema = z.string().uuid();

/**
 * Wire request envelope. `module`/`action` are exact allowlisted strings and
 * `version` is the module API major version. `payload` is validated per
 * command.
 */
export const requestEnvelopeSchema = z.object({
  requestId: requestIdSchema,
  module: z.string().min(1).max(64),
  version: z.number().int().positive(),
  action: z.string().min(1).max(128),
  payload: z.unknown(),
});

export type RequestEnvelope = z.infer<typeof requestEnvelopeSchema>;

/**
 * What the renderer passes to `window.career.request`; requestId is added in
 * preload.
 */
export type RequestInput = {
  module: string;
  version: number;
  action: string;
  payload?: unknown;
};

export const successEnvelopeSchema = z.object({
  requestId: requestIdSchema,
  ok: z.literal(true),
  data: z.unknown(),
});

export const failureEnvelopeSchema = z.object({
  requestId: requestIdSchema,
  ok: z.literal(false),
  error: errorPayloadSchema,
});

export const responseEnvelopeSchema = z.discriminatedUnion('ok', [
  successEnvelopeSchema,
  failureEnvelopeSchema,
]);

export type SuccessEnvelope<T = unknown> = {
  requestId: string;
  ok: true;
  data: T;
};

export type FailureEnvelope = z.infer<typeof failureEnvelopeSchema>;

export type ResponseEnvelope<T = unknown> =
  | SuccessEnvelope<T>
  | FailureEnvelope;
